LogicDev 시스템 가동. `script.js` 내 핵심 게임 로직 구현을 시작합니다. 본 설계는 연산 복잡도를 최소화하고 상태 무결성을 보장하는 데 중점을 둡니다.

### 1. 기술적 설계 개요
*   **데이터 구조**: 1차원 배열(`state`)을 사용하여 메모리 참조 효율을 높이고 인덱스 연산을 단순화합니다.
*   **승리 판별 최적화**: 매 수마다 모든 경우의 수를 탐색하는 대신, 미리 정의된 승리 조합(Lookup Table)을 참조하여 $O(1)$에 가까운 효율을 지향합니다.
*   **방어적 설계**: 상태 변경 전 유효성 검사(Validation)를 선행하여 데이터 오염을 방지합니다.

---

### 2. Core Logic Implementation (`script.js`)

```javascript
/**
 * LogicDev Game Engine v1.0
 * Architecture: Finite State Machine (FSM) based Logic
 */

const GameEngine = (() => {
    // 1. 초기 설정 및 상수 선언
    const CONFIG = {
        PLAYER_X: 'X',
        PLAYER_O: 'O',
        GRID_SIZE: 9,
        WIN_COMBINATIONS: [
            [0, 1, 2], [3, 4, 5], [6, 7, 8], // Rows
            [0, 3, 6], [1, 4, 7], [2, 5, 8], // Columns
            [0, 4, 8], [2, 4, 6]             // Diagonals
        ]
    };

    // 2. 게임 상태 (Encapsulated State)
    let state = {
        board: Array(CONFIG.GRID_SIZE).fill(null),
        currentPlayer: CONFIG.PLAYER_X,
        isActive: true,
        movesCount: 0
    };

    /**
     * 승리 및 무승부 조건 검사
     * @returns {string|null} 'X', 'O', 'Draw', 또는 게임 진행 중일 경우 null
     */
    const checkGameStatus = () => {
        const { board, WIN_COMBINATIONS, movesCount } = state;

        for (const [a, b, c] of WIN_COMBINATIONS) {
            if (board[a] && board[a] === board[b] && board[a] === board[c]) {
                return board[a];
            }
        }

        return movesCount === CONFIG.GRID_SIZE ? 'Draw' : null;
    };

    /**
     * 셀 클릭 이벤트 핸들러
     * @param {number} index - 클릭된 셀의 인덱스 (0-8)
     */
    const handleCellClick = (index) => {
        // Edge Case: 이미 점유된 셀이거나 게임이 종료된 경우 처리 거부
        if (!state.isActive || state.board[index] !== null) {
            return { success: false, reason: 'Invalid Move' };
        }

        // 상태 업데이트 (Mutation)
        state.board[index] = state.currentPlayer;
        state.movesCount++;

        const result = checkGameStatus();

        if (result) {
            state.isActive = false;
            return { success: true, status: 'End', winner: result };
        }

        // 플레이어 교체 (Toggling)
        state.currentPlayer = state.currentPlayer === CONFIG.PLAYER_X ? CONFIG.PLAYER_O : CONFIG.PLAYER_X;
        return { success: true, status: 'Continue', nextPlayer: state.currentPlayer };
    };

    /**
     * 게임 초기화
     */
    const resetGame = () => {
        state = {
            board: Array(CONFIG.GRID_SIZE).fill(null),
            currentPlayer: CONFIG.PLAYER_X,
            isActive: true,
            movesCount: 0
        };
        return { success: true, message: 'Game Reset' };
    };

    // 인터페이스 노출
    return {
        handleCellClick,
        resetGame,
        getState: () => ({ ...state }) // 상태 스냅샷 제공 (불변성 유지)
    };
})();

// UI 브릿지 (Event Listeners & Rendering)
document.addEventListener('DOMContentLoaded', () => {
    const cells = document.querySelectorAll('.cell');
    const statusDisplay = document.querySelector('#status');
    const resetButton = document.querySelector('#reset-btn');

    const updateUI = (result) => {
        const currentState = GameEngine.getState();

        // 보드 렌더링 동기화
        currentState.board.forEach((val, idx) => {
            cells[idx].textContent = val;
        });

        if (result?.status === 'End') {
            statusDisplay.textContent = result.winner === 'Draw' ? "It's a Draw!" : `Player ${result.winner} Wins!`;
        } else {
            statusDisplay.textContent = `Next Player: ${currentState.currentPlayer}`;
        }
    };

    cells.forEach(cell => {
        cell.addEventListener('click', (e) => {
            const index = parseInt(e.target.dataset.index);
            const moveResult = GameEngine.handleCellClick(index);
            if (moveResult.success) updateUI(moveResult);
        });
    });

    resetButton.addEventListener('click', () => {
        GameEngine.resetGame();
        updateUI();
        statusDisplay.textContent = `Next Player: X`;
    });
});
```

---

### 3. 기술적 타당성 검토

1.  **메모리 효율성**: `CONFIG.WIN_COMBINATIONS`를 클로저 외부가 아닌 내부에 정적으로 선언하여 전역 오염을 방지하고 메모리 참조를 최적화했습니다.
2.  **방어적 프로그래밍**: `handleCellClick` 함수 내에서 `state.isActive`와 중복 클릭 여부를 가장 먼저 확인(Guard Clause)함으로써 불필요한 연산을 원천 차단합니다.
3.  **데이터 무결성**: `getState()` 호출 시 스프레드 연산자(`...state`)를 사용하여 상태 객체의 참조가 아닌 복사본을 반환합니다. 이는 외부 UI 로직이 내부 엔진 상태를 직접 조작하는 위험을 방지합니다.
4.  **확장성**: 3x3 격자를 넘어서는 $N \times N$ 구조로 변경 시 `CONFIG` 객체와 `WIN_COMBINATIONS` 생성 로직만 수정하면 엔진 핵심 로직은 그대로 재사용 가능합니다.

